<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { supabase } from './lib/supabase'

type Plan = { id: string; name: string; price_cents: number; character_limit: number; description: string; glyph: string }
type Character = { id: string; name: string; species: string; role: string; level: number; health: number; max_health: number; experience: number; abilities: string; biography: string }

const router = useRouter()
const route = useRoute()
const busy = ref(false)
const notice = ref('')
const authMode = ref<'login' | 'register'>('login')
const user = ref<{ email: string; display_name: string }>({ email: 'warden@chronicles.gg', display_name: 'Mira Stone' })
const selectedCharacter = ref<Character | null>(null)
const activeTab = ref('overview')
const modal = ref<'plan' | 'delete' | null>(null)
const chosenPlan = ref<Plan | null>(null)
const characterToDelete = ref<Character | null>(null)

const plans: Plan[] = [
  { id: 'free', name: 'Wanderer', price_cents: 0, character_limit: 10, description: 'For players beginning their first saga.', glyph: '✦' },
  { id: 'adventurer', name: 'Adventurer', price_cents: 500, character_limit: 15, description: 'Room to gather a legendary party.', glyph: '⚔' },
  { id: 'hero', name: 'Hero', price_cents: 1000, character_limit: 25, description: 'For storytellers with many worlds.', glyph: '♜' },
  { id: 'legend', name: 'Legend', price_cents: 1500, character_limit: 50, description: 'The complete chronicle keeper.', glyph: '♛' },
]
const currentPlan = ref<Plan>(plans[1])
const characters = ref<Character[]>([
  { id: '1', name: 'Aeliana Voss', species: 'Moon Elf', role: 'Spellblade', level: 7, health: 42, max_health: 50, experience: 1840, abilities: 'Glimmerstep, Arcane Ward, Silver Thread', biography: 'A quiet star with a dangerous past. Aeliana learned the blade to protect the magic she could not control.' },
  { id: '2', name: 'Bramble Underbough', species: 'Halfling', role: 'Wayfinder', level: 4, health: 28, max_health: 32, experience: 760, abilities: 'Keen Eye, Lucky Break', biography: 'A mapmaker who believes every road has a story worth following.' },
  { id: '3', name: 'Kael Ironhand', species: 'Human', role: 'Vanguard', level: 9, health: 61, max_health: 74, experience: 2860, abilities: 'Bulwark, Rallying Cry, Iron Resolve', biography: 'The last shield of a fallen order, carrying a promise heavier than steel.' },
])
const form = reactive({ email: '', password: '', confirm: '', displayName: '' })
const newCharacter = reactive({ name: '', species: '', role: '', level: 1, health: 10, max_health: 10, experience: 0, abilities: '', biography: '' })
const attributes = ref([{ name: 'Strength', value: '10' }, { name: 'Dexterity', value: '10' }])
const journal = ref([{ date: '2025-02-14', campaign: 'The Shattered Crown', title: 'The bell beneath Blackwater', players: 'Mira, Juno, Felix', events: 'Found the submerged bell and heard a voice answer from below.', rewards: 'Moon-silver key', notes: 'The tide is moving against the moon.' }])
const equipment = ref([{ item_name: 'Moon-silver rapier', item_type: 'Weapon', quantity: 1, description: 'A blade that catches light from impossible angles.' }, { item_name: 'Healing draught', item_type: 'Consumable', quantity: 3, description: 'Warm as cinnamon, bright as dawn.' }])

const path = computed(() => route.path)
const isAuthPage = computed(() => path.value === '/login' || path.value === '/register')
const isNew = computed(() => path.value === '/characters/new')
const usage = computed(() => characters.value.length)
const isDetail = computed(() => path.value.startsWith('/characters/') && path.value !== '/characters/new' && path.value.endsWith('') && selectedCharacter.value)

function go(to: string) { notice.value = ''; router.push(to) }
function formatPrice(cents: number) { return cents === 0 ? 'Free' : `$${(cents / 100).toFixed(0)}` }
function selectCharacter(character: Character) { selectedCharacter.value = character; activeTab.value = String(route.query.tab || 'overview'); go(`/characters/${character.id}?tab=${activeTab.value}`) }
function openPlan(plan: Plan) { chosenPlan.value = plan; modal.value = 'plan' }
function switchPlan() { if (chosenPlan.value) currentPlan.value = chosenPlan.value; modal.value = null; notice.value = `Your plan is now ${chosenPlan.value?.name}. Welcome to the next chapter.` }
function addAttribute() { attributes.value.push({ name: '', value: '' }) }
function removeAttribute(index: number) { attributes.value.splice(index, 1) }
function useDefaults() { attributes.value = ['Strength', 'Dexterity', 'Constitution', 'Intelligence', 'Wisdom', 'Charisma'].map(name => ({ name, value: '10' })) }
function saveCharacter() { if (!newCharacter.name.trim()) { notice.value = 'Give your character a name before continuing.'; return }; const character: Character = { id: String(Date.now()), ...newCharacter, name: newCharacter.name.trim() }; characters.value.push(character); notice.value = `${character.name} has joined your chronicles.`; go('/characters') }
function confirmDelete(character: Character) { characterToDelete.value = character; modal.value = 'delete' }
function deleteCharacter() { if (characterToDelete.value) characters.value = characters.value.filter(item => item.id !== characterToDelete.value?.id); modal.value = null; characterToDelete.value = null; notice.value = 'Character and their connected journal have been removed.' }
function submitAuth() { busy.value = true; window.setTimeout(() => { busy.value = false; if (authMode.value === 'register') user.value = { email: form.email || 'warden@chronicles.gg', display_name: form.displayName || 'New Warden' }; go('/characters') }, 500) }
function signOut() { user.value = { email: '', display_name: '' }; go('/login') }
onMounted(async () => { const { data } = await supabase.auth.getUser(); if (data.user) user.value = { email: data.user.email || '', display_name: data.user.user_metadata?.display_name || data.user.email?.split('@')[0] || 'Warden' } })
</script>

<template>
  <div class="app-shell">
    <span class="corner-mark corner-top">🌿</span><span class="corner-mark corner-bottom">🔥</span>
    <main class="frame">
      <header v-if="!isAuthPage" class="site-header">
        <div><div class="eyebrow">The chronicle keeper</div><h1>RPG Campaign Chronicles</h1><p class="welcome">Welcome, {{ user.display_name || 'Warden' }} <span>· Tier: {{ currentPlan.name }}</span></p></div>
        <nav><button :class="{ active: path === '/characters' }" @click="go('/characters')">Characters</button><button :class="{ active: path === '/plans' }" @click="go('/plans')">Plans</button><button :class="{ active: path === '/account' }" @click="go('/account')">Account</button><button class="logout" @click="signOut">Logout</button></nav>
      </header>
      <div v-if="notice" class="notice">{{ notice }}<button @click="notice = ''">×</button></div>

      <section v-if="isAuthPage" class="auth-layout">
        <div class="auth-art"><div class="sigil">✦</div><p class="eyebrow">A living archive for your next adventure</p><h2>Every hero<br><em>has a story.</em></h2><p>Keep your party, your gear, and every hard-won session close at hand.</p><div class="constellation">✧ · ˚ · ✦ · ˚ · ✧</div></div>
        <form class="auth-card" @submit.prevent="submitAuth"><div class="eyebrow">{{ authMode === 'login' ? 'Return to the archive' : 'Begin your legend' }}</div><h2>{{ authMode === 'login' ? 'Welcome back' : 'Create your account' }}</h2><p class="muted">{{ authMode === 'login' ? 'Your next chapter awaits.' : 'No payment required. Start your chronicle free.' }}</p>
          <label v-if="authMode === 'register'">Display name<input v-model="form.displayName" placeholder="What shall we call you?" /></label><label>Email<input v-model="form.email" type="email" placeholder="you@realm.com" required /></label><label>Password<input v-model="form.password" type="password" placeholder="8+ characters, letter and number" required /></label><label v-if="authMode === 'register'">Confirm password<input v-model="form.confirm" type="password" required /></label><button class="primary full" :disabled="busy">{{ busy ? 'Opening the archive…' : authMode === 'login' ? 'Enter the chronicles' : 'Create my account' }}</button><p class="switch">{{ authMode === 'login' ? 'New to the guild?' : 'Already have an account?' }} <button type="button" @click="authMode = authMode === 'login' ? 'register' : 'login'">{{ authMode === 'login' ? 'Create an account' : 'Sign in' }}</button></p>
        </form>
      </section>

      <template v-else>
        <section v-if="path === '/' || path === '/characters'" class="page"><div class="page-heading"><div><div class="eyebrow">Your active roster</div><h2>Characters <span class="count-pill">{{ usage }} / {{ currentPlan.character_limit }}</span></h2><p class="muted">The heroes who carry your story forward.</p></div><button class="primary" :disabled="usage >= currentPlan.character_limit" @click="go('/characters/new')">＋ Create new character</button></div><div v-if="usage >= currentPlan.character_limit" class="warning">Your {{ currentPlan.name }} plan is full. <button @click="go('/plans')">Upgrade your plan</button> to create another hero.</div><div v-if="!characters.length" class="empty"><div class="empty-glyph">✦</div><h3>No characters yet</h3><p>Create your first hero and give them a place in the chronicles.</p></div><div v-else class="character-grid"><article v-for="character in characters" :key="character.id" class="character-card"><div class="card-top"><span class="level">LVL {{ character.level }}</span><span class="card-menu">✧</span></div><div class="avatar">{{ character.name.charAt(0) }}</div><h3>{{ character.name }}</h3><p class="species">{{ character.species || 'Unknown' }} <span>·</span> {{ character.role || 'Adventurer' }}</p><div class="health-row"><span>Vitality</span><strong>{{ character.health }}<small>/{{ character.max_health }}</small></strong></div><div class="health-track"><i :style="{ width: `${Math.min(100, character.health / Math.max(1, character.max_health) * 100)}%` }"></i></div><div class="card-actions"><button @click="selectCharacter(character)">View</button><button @click="go(`/characters/${character.id}/edit`)">Edit</button><button class="danger-text" @click="confirmDelete(character)">Delete</button></div></article></div></section>

        <section v-else-if="path === '/plans'" class="page"><div class="center-heading"><div class="eyebrow">Choose your chapter</div><h2>Plans for every kind of story</h2><p class="muted">Start free, then make room for the legends still waiting to be written.</p></div><div class="plans-grid"><article v-for="plan in plans" :key="plan.id" class="plan-card" :class="{ featured: plan.id === 'adventurer' }"><span v-if="plan.id === 'adventurer'" class="ribbon">Popular</span><div class="plan-glyph">{{ plan.glyph }}</div><div class="eyebrow">{{ plan.name }}</div><h3>{{ formatPrice(plan.price_cents) }} <small v-if="plan.price_cents">/ month</small></h3><p class="muted">{{ plan.description }}</p><div class="plan-limit"><strong>{{ plan.character_limit }}</strong><span>character slots</span></div><button v-if="currentPlan.id === plan.id" class="outline full" disabled>Current plan</button><button v-else class="primary full" @click="openPlan(plan)">Choose {{ plan.name }}</button></article></div></section>

        <section v-else-if="isNew || path.endsWith('/edit')" class="page form-page"><button class="back-link" @click="go('/characters')">← Back to characters</button><div class="eyebrow">{{ isNew ? 'New entry' : 'Edit entry' }}</div><h2>{{ isNew ? 'Create a character' : 'Shape your character' }}</h2><p class="muted">Only a name is required. The rest of their story can unfold over time.</p><form class="character-form" @submit.prevent="saveCharacter"><div class="form-section"><h3>Identity</h3><div class="form-grid"><label class="wide">Name *<input v-model="newCharacter.name" placeholder="A name worthy of song" required /></label><label>Species<input v-model="newCharacter.species" placeholder="Moon Elf" /></label><label>Role<input v-model="newCharacter.role" placeholder="Spellblade" /></label></div></div><div class="form-section"><h3>Core stats</h3><div class="form-grid"><label>Level<input v-model.number="newCharacter.level" type="number" min="0" /></label><label>Health<input v-model.number="newCharacter.health" type="number" min="0" /></label><label>Max health<input v-model.number="newCharacter.max_health" type="number" min="0" /></label><label>Experience<input v-model.number="newCharacter.experience" type="number" min="0" /></label></div></div><div class="form-section"><h3>Custom attributes</h3><div v-for="(attribute, index) in attributes" :key="index" class="attribute-row"><input v-model="attribute.name" placeholder="Attribute name" /><input v-model="attribute.value" placeholder="Value" /><button type="button" @click="removeAttribute(index)">×</button></div><div class="attribute-actions"><button type="button" class="small-button" @click="addAttribute">＋ Add attribute</button><button type="button" class="small-button gold-button" @click="useDefaults">Use D&D defaults</button></div></div><div class="form-section"><h3>Story</h3><label>Powers & abilities<textarea v-model="newCharacter.abilities" rows="3" placeholder="What can they do that others cannot?"></textarea></label><label>Backstory<textarea v-model="newCharacter.biography" rows="4" placeholder="Every legend begins somewhere…"></textarea></label></div><button class="primary" type="submit">{{ isNew ? 'Add to the chronicles' : 'Save changes' }}</button></form></section>

        <section v-else-if="isDetail" class="page"><button class="back-link" @click="go('/characters')">← Back to characters</button><div class="profile-head"><div class="avatar large">{{ selectedCharacter?.name.charAt(0) }}</div><div><div class="eyebrow">Level {{ selectedCharacter?.level }} · {{ selectedCharacter?.role }}</div><h2>{{ selectedCharacter?.name }}</h2><p class="species">{{ selectedCharacter?.species }} · {{ selectedCharacter?.health }}/{{ selectedCharacter?.max_health }} vitality</p></div><button class="outline" @click="go(`/characters/${selectedCharacter?.id}/edit`)">Edit character</button></div><div class="tabs"><button :class="{ active: activeTab === 'overview' }" @click="activeTab = 'overview'; go(`/characters/${selectedCharacter?.id}?tab=overview`)">Overview</button><button :class="{ active: activeTab === 'equipment' }" @click="activeTab = 'equipment'; go(`/characters/${selectedCharacter?.id}?tab=equipment`)">Equipment <span>2</span></button><button :class="{ active: activeTab === 'journal' }" @click="activeTab = 'journal'; go(`/characters/${selectedCharacter?.id}?tab=journal`)">Journal <span>1</span></button></div><div v-if="activeTab === 'overview'" class="detail-grid"><div class="detail-card"><div class="eyebrow">Powers & abilities</div><p>{{ selectedCharacter?.abilities || 'No abilities recorded yet.' }}</p></div><div class="detail-card"><div class="eyebrow">Backstory</div><p>{{ selectedCharacter?.biography || 'This story is still being written.' }}</p></div><div class="detail-card"><div class="eyebrow">Custom attributes</div><div v-for="attribute in attributes.slice(0, 4)" :key="attribute.name" class="stat-line"><span>{{ attribute.name }}</span><strong>{{ attribute.value }}</strong></div><button class="text-link">＋ Add attribute</button></div><div class="detail-card stat-highlight"><div class="eyebrow">Experience</div><strong>{{ selectedCharacter?.experience }} XP</strong><div class="xp-track"><i style="width: 62%"></i></div><small>Next level · 1,200 XP</small></div></div><div v-else-if="activeTab === 'equipment'" class="detail-card wide-detail"><div class="section-heading"><div><div class="eyebrow">What they carry</div><h3>Equipment</h3></div><button class="primary">＋ Add item</button></div><div v-for="item in equipment" :key="item.item_name" class="item-row"><div class="item-icon">✦</div><div><strong>{{ item.item_name }}</strong><small>{{ item.item_type }} · {{ item.description }}</small></div><span class="quantity">×{{ item.quantity }}</span><button class="icon-button">⋮</button></div></div><div v-else class="wide-detail"><div class="section-heading"><div><div class="eyebrow">The story so far</div><h3>Session journal</h3></div><button class="primary">＋ New entry</button></div><article v-for="entry in journal" :key="entry.title" class="journal-entry"><div class="journal-date"><strong>{{ entry.date.slice(8) }}</strong><span>{{ entry.date.slice(0, 7) }}</span></div><div><div class="eyebrow">{{ entry.campaign }}</div><h3>{{ entry.title }}</h3><p>{{ entry.events }}</p><div class="journal-meta"><span>Players: {{ entry.players }}</span><span>Rewards: {{ entry.rewards }}</span></div></div></article></div></section>

        <section v-else-if="path === '/account'" class="page"><div class="eyebrow">Your keeper profile</div><h2>Account</h2><div class="account-grid"><div class="detail-card"><div class="eyebrow">Identity</div><h3>{{ user.display_name }}</h3><p class="muted">{{ user.email }}</p><button class="outline">Edit profile</button></div><div class="detail-card plan-summary"><div class="eyebrow">Current plan</div><h3>{{ currentPlan.name }}</h3><p>{{ formatPrice(currentPlan.price_cents) }} <span v-if="currentPlan.price_cents">per month</span></p><button class="text-link" @click="go('/plans')">Compare plans →</button></div><div class="detail-card usage-card"><div class="section-heading"><div><div class="eyebrow">Character usage</div><h3>{{ usage }} of {{ currentPlan.character_limit }} slots used</h3></div><strong>{{ currentPlan.character_limit - usage }} remaining</strong></div><div class="usage-track"><i :style="{ width: `${usage / currentPlan.character_limit * 100}%` }"></i></div><p class="muted">Your chronicles have room to grow.</p></div></div></section>
      </template>
      <footer v-if="!isAuthPage"><span>RPG Campaign Chronicles</span><div><a href="#">Twitter 🐦</a><a href="#">Discord 🎮</a><a href="#">Patreon 🛡️</a></div></footer>
    </main>
    <div v-if="modal" class="modal-backdrop" @click.self="modal = null"><div class="modal"><button class="modal-close" @click="modal = null">×</button><template v-if="modal === 'plan'"><div class="plan-glyph">{{ chosenPlan?.glyph }}</div><div class="eyebrow">Confirm your next chapter</div><h2>Switch to {{ chosenPlan?.name }}?</h2><p>{{ formatPrice(chosenPlan?.price_cents || 0) }}<span v-if="chosenPlan?.price_cents">/month</span> · {{ chosenPlan?.character_limit }} characters.</p><p class="muted">This is a simulated plan change; no payment is collected.</p><button class="primary full" @click="switchPlan">Confirm plan change</button></template><template v-else><div class="danger-icon">!</div><div class="eyebrow">A permanent choice</div><h2>Delete {{ characterToDelete?.name }}?</h2><p class="muted">Their attributes, equipment, and journal will be deleted too.</p><div class="modal-actions"><button class="outline" @click="modal = null">Keep character</button><button class="danger full" @click="deleteCharacter">Delete character</button></div></template></div></div>
  </div>
</template>
